using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Globalization;
using System.Text;
using static System.Console;
using static TextAlgorithms;
using static Intervals;

class Program
{
    private const int N = 9;
    private const int TextLength = 49749;

    static double Time(Action run) => Measurements.Best(run);
    static void Main()
    {
        string text = Prose.Text;
        var words = text.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
        WriteLine("## Три пастки\n\n| Додавань | +=, мс | StringBuilder, мс |\n|---:|---:|---:|");
        foreach (int n in new[] { 10000, 100000 })
        {
            double slow = Time(() => { string s = ""; for (int i = 0; i < n; i++) s += 'М'; GC.KeepAlive(s); });
            double fast = Time(() => { var s = new StringBuilder(n); for (int i = 0; i < n; i++) s.Append('М'); GC.KeepAlive(s.ToString()); });
            WriteLine($"| {n} | {slow:F3} | {fast:F3} |");
        }
        WriteLine("\nКожне += копіює вже накопичений префікс. StringBuilder записує символи в буфер.");
        int matches = 0;
        double lower = Time(() => { matches = 0; for (int i = 0; i < 100000; i++) if (words[i % words.Length].ToLower() == words[(i + 1) % words.Length].ToLower()) matches++; });
        double ignore = Time(() => { matches = 0; for (int i = 0; i < 100000; i++) if (string.Equals(words[i % words.Length], words[(i + 1) % words.Length], StringComparison.OrdinalIgnoreCase)) matches++; });
        WriteLine($"\n100 000 пар: ToLower — {lower:F3} мс, OrdinalIgnoreCase — {ignore:F3} мс. Другий спосіб порівнює без створення двох копій слів.");
        string[] sample = "гава ґава ганок ґанок гніт ґніт гра ґрати гудзик ґудзик гора ґазда дім дуб єнот їжак кіт хата яма сад".Split(' ');
        var ordinal = (string[])sample.Clone(); var ukrainian = (string[])sample.Clone();
        double ord = Time(() => { sample.CopyTo(ordinal, 0); Array.Sort(ordinal, StringComparer.Ordinal); });
        double cult = Time(() => { sample.CopyTo(ukrainian, 0); Array.Sort(ukrainian, StringComparer.Create(new CultureInfo("uk-UA"), false)); });
        WriteLine($"\nOrdinal ({ord:F4} мс) — {string.Join(", ", ordinal)}.\n\nuk-UA ({cult:F4} мс) — {string.Join(", ", ukrainian)}. Український порядок ставить ґ після г. В Ordinal позицію визначає код UTF-16.");
        WriteLine("\n## Найдовший підрядок без повторів\n\n| Символів | Наївно, мс | Вікно, мс | Виграш | Довжина |\n|---:|---:|---:|---:|---:|");
        double finalSlow = 0, finalFast = 0;
        foreach (int n in new[] { 1000, 10000, TextLength })
        {
            string slice = text[..n]; Agree(slice);
            finalSlow = Time(() => Naive(slice)); finalFast = Time(() => Window(slice));
            WriteLine($"| {n} | {finalSlow:F4} | {finalFast:F4} | {finalSlow / finalFast:F2} | {Window(slice).Length} |");
        }
        WriteLine("\n## Пошук підрядка\n\n| Вхід | Шаблон | Індекс | Порівнянь | Власний, мс | IndexOf, мс |\n|---|---|---:|---:|---:|---:|");
        foreach (var (source, pattern, label) in new[] { (text, "Канівщина", "проза"), (text, "електросамокат", "проза"), (new string('М', 10000), new string('М', 1069) + "Н", "повтори") })
        {
            int pos = TextAlgorithms.IndexOf(source, pattern, out int c);
            if (pos != source.IndexOf(pattern, StringComparison.Ordinal)) throw new Exception();
            WriteLine($"| {label} | {(pattern.Length > 30 ? "1069 × М + Н" : pattern)} | {pos} | {c} | {Time(() => TextAlgorithms.IndexOf(source, pattern, out _)):F4} | {Time(() => source.IndexOf(pattern, StringComparison.Ordinal)):F4} |");
        }
        WriteLine("\nНа повторах кожен початок збігається аж до останньої літери шаблону. Бібліотечний пошук може відкидати кандидатів блоками. Його внутрішні порівняння тут не підраховувалися.");
        Random random = new Random(N);
        int wins = 0;
        Interval[] Generate(int n)
        {
            var data = new Interval[n];
            for (int i = 0; i < n; i++) { int start = random.Next(44); data[i] = new(start, random.Next(start + 1, 45)); }
            return data;
        }
        for (int t = 0; t < 100; t++) { var data = Generate(random.Next(1, 16)); if (Greedy(data, Finish) == Exact(data, false, out _)) wins++; }
        if (wins != 100) throw new Exception("Жадібний вибір програв");
        WriteLine($"\n## Заявки [початок, кінець)\n\nОптимум у {wins}/100 тестах. Найгірше відставання 0%. Раніше завершення залишає щонайменше стільки часу для решти заявок, як будь-який інший перший вибір.");
        Interval[] early = [new(0, 10), new(1, 3), new(3, 5)];
        Interval[] shortFirst = [new(0, 4), new(3, 5), new(4, 8)];
        WriteLine($"\nРанній початок: [0,10), [1,3), [3,5) → {Greedy(early, (x, y) => x.Start.CompareTo(y.Start))} замість {Exact(early, false, out _)}.");
        WriteLine($"\nНайкоротша заявка: [0,4), [3,5), [4,8) → {Greedy(shortFirst, (x, y) => (x.End - x.Start).CompareTo(y.End - y.Start))} замість {Exact(shortFirst, false, out _)}.");
        WriteLine("\n| Заявок | Перебір, мс | Відсікання, мс | Вузлів без / з відсіканням |\n|---:|---:|---:|---:|");
        foreach (int n in new[] { 15, 20 })
        {
            var data = Generate(n);
            if (Exact(data, false, out long full) != Exact(data, true, out long cut)) throw new Exception();
            WriteLine($"| {n} | {Time(() => Exact(data, false, out _)):F4} | {Time(() => Exact(data, true, out _)):F4} | {full} / {cut} |");
        }
        WriteLine("\n## Крайові випадки\n\n| Запит | Очікувано | Отримано |\n|---|---|---|");
        foreach (var (s, expected) in new[] { ("", ""), ("я", "я"), ("ммм", "м"), ("  аб  в ", " аб") })
        {
            Agree(s); string actual = Window(s);
            if (actual != expected) throw new Exception("Межа вікна");
            WriteLine($"| вікно «{s}» | «{expected}» | «{actual}» |");
        }
        foreach (var (s, p, expected) in new[] { ("", "а", -1), ("а", "аб", -1), ("аб", "", 0) })
        {
            int actual = TextAlgorithms.IndexOf(s, p, out _); if (actual != expected) throw new Exception();
            WriteLine($"| пошук «{p}» у «{s}» | {expected} | {actual} |");
        }
        foreach (Interval[] data in new Interval[][] { [], [new(1, 2)] })
        {
            int actual = Greedy(data, Finish); if (actual != data.Length || Exact(data, false, out _) != actual) throw new Exception();
            WriteLine($"| заявок {data.Length} | {data.Length} | {actual} |");
        }
        WriteLine($"\n## Вибір алгоритму\n\n1. Вхід — уривок прози, найбільший замір на 49 749 символів.\n2. На кожен із трьох розмірів потрібен один найдовший підрядок. За рівної довжини повертається перший.\n3. Текст між запитами сталий, для нового уривка вікно запускається з початку.\n4. На повному уривку важливий час: {finalSlow:F4} проти {finalFast:F4} мс. Наївний метод повторно перевіряє пари, швидкий зберігає множину символів поточного вікна.\n5. HashSet<char> дає додавання й вилучення символу в середньому за сталий час.\n6. На 49 749 символів обрано ковзне вікно, виграш {finalSlow / finalFast:F2} раза. Короткі серії без повторів у прозі обмежують витрати наївного методу.");
    }
}

static class TextAlgorithms
{
    // Для кожного початку перевіряємо кожного кандидата заново.
    // Після першого повтору всі довші підрядки з цим початком теж містять повтор.
    public static string Naive(string text)
    {
        int start = 0, best = 0;
        for (int i = 0; i < text.Length; i++)
            for (int end = i; end < text.Length; end++)
            {
                bool unique = true;
                for (int j = i; j <= end && unique; j++)
                    for (int k = i; k < j; k++)
                        if (text[k] == text[j]) { unique = false; break; }
                if (!unique) break;
                if (end - i + 1 > best) { start = i; best = end - i + 1; }
            }
        return text.Substring(start, best);
    }
    public static string Window(string text)
    {
        int left = 0, start = 0, best = 0;
        var seen = new HashSet<char>();
        for (int right = 0; right < text.Length; right++)
        {
            while (!seen.Add(text[right])) seen.Remove(text[left++]);
            if (right - left + 1 > best) { start = left; best = right - left + 1; }
        }
        return text.Substring(start, best);
    }
    public static void Agree(string text)
    {
        if (!string.Equals(Naive(text), Window(text), StringComparison.Ordinal)) throw new Exception("Різні підрядки");
    }
    public static int IndexOf(string text, string pattern, out int comparisons)
    {
        comparisons = 0;
        for (int i = 0; i <= text.Length - pattern.Length; i++)
        {
            int j = 0;
            while (j < pattern.Length)
            {
                comparisons++;
                if (text[i + j] != pattern[j]) break;
                j++;
            }
            if (j == pattern.Length) return i;
        }
        return -1;
    }
}

record struct Interval(int Start, int End);

static class Intervals
{
    public static int Greedy(Interval[] input, Comparison<Interval> order)
    {
        var sorted = (Interval[])input.Clone();
        Array.Sort(sorted, order);
        var accepted = new List<Interval>();
        foreach (var next in sorted)
        {
            bool fits = true;
            foreach (var previous in accepted)
                if (next.Start < previous.End && previous.Start < next.End) { fits = false; break; }
            if (fits) accepted.Add(next);
        }
        return accepted.Count;
    }
    public static readonly Comparison<Interval> Finish = (x, y) => x.End.CompareTo(y.End);
    public static int Exact(Interval[] input, bool prune, out long nodes)
    {
        var sorted = (Interval[])input.Clone();
        Array.Sort(sorted, (x, y) => x.Start.CompareTo(y.Start));
        long visited = 0;
        int best = 0;
        void Visit(int index, int end, int count)
        {
            visited++;
            if (index == sorted.Length) { best = Math.Max(best, count); return; }
            if (prune && count + sorted.Length - index <= best) return;
            if (sorted[index].Start >= end) Visit(index + 1, sorted[index].End, count + 1);
            Visit(index + 1, end, count);
        }
        Visit(0, int.MinValue, 0);
        nodes = visited;
        return best;
    }
}

static class Measurements
{
    public static double Best(Action run)
    {
        run();
        double best = double.MaxValue;
        for (int trial = 0; trial < 3; trial++)
        {
            var timer = Stopwatch.StartNew();
            run();
            timer.Stop();
            best = Math.Min(best, timer.Elapsed.TotalMilliseconds);
        }
        return best;
    }
}

static class Prose
{
    public const string Text =
        "Кайдашева сімя̀ — I\n" +
        "Иван Левіцький\n" +
        "1879\n" +
        "Вся Канівщина од самого берега Дніпра вкрита крутими горами, — але нігде нема таких крутих та густих гір, як на полуденній стороні Канівщини, де річка Рось наближається до Дніпра, де вона прорізує гори и під горами камянний шар, де обидва береги Росі обставляні скелями. Глянеш с корсунських гір, славних битвами Богдана Хмельницького и по обидва боки Росі земля ніби схопилася пухирями та бульками, ніби вона кипіла, клекотіла и тільки що простигла саме тоді, як добре вбилася в ключі. Здається, ніби то не земля, а море в час бурі з високими та крутими хвилями, с кучерявими гребінями. Скрізь понад Россю стоять круті гори, як висока покрівля хат, поломані на всі боки; між горами узькі та довгі, без кінця, ярі, покручені, як безконечник на писанках. Гори то піднімаються, то вгинаються на всі боки, то западають дуже глибококруглими глибокими долинками похожими на погріб. На іх крутих ребрах подекуди ніби хтось повиколупував долинки якоюсь велитенською ложкою. На тих горах скрізь стремлять козацькі могили, куди тільки кинеш оком. Ввесь край ніби якесь здорове кладовище, де похований цілий народ, де під безлічними могилами похована украінська воля. Вся краіна без ліса, гола, спустошена. Лісів зосталось небогато. Тільки в ті долини та ярі поховались чудові, пишні села та хуторі с садками та ставками. Вся сторона густо засипана селами, як рясна яблоня яблуками. Виідеш з глибокого яру на високу круту гору, а за тією горою роскинеться долина, вся вкрита травою, ніби зеленими килимами, на котрих роскидані роскішні букети садів з білими, як сніг, хатами, з блискучими ставками, з зеленими купами верб по над ставками. Зъідеш с крутоі гори в глибокий яр, и перед тобою на всі боки неначе одчиняються ворота між крутими горбами, а через ті ворота виглядають то села з зеленими садами та городами в глибоких закутках, то зелені бані церков, то зелені байраки на крутих ребрах, то голі боки гір, літом попаляні сонцем, то здорові сахарні с чорними високими виводами коло ставків, то часом густий, як щетина, дубовий старий ліс. Вискочиш на другу гору и знов перед тобою міняється декорация: в низу блищить глибока кругла узька долина, неначе здорова миска, вся обросла чегарником, а на самому дні долини лежить довгий невеликий горб, ввесь порослий густими кущами, неначе якийсь зелений здоровий іжак притаівся на дні долини. А там по другий бік шляху між горами вється Рось од Стеблева до Корсуня; по над Россю скрізь млини, коло млинів високі верби, хати з зеленими огородами. В воді сіріє здорове каміння, до котрого притулились букети ліз та високого очерету. Над берегами стремлять скелі, сіріє й червоніє каміння, що повисовувалось з землі на світ божий, неначе повисовувались сухі ребра.\n" +
        "В літній час те давнє кладовище украінськоі историі й тепер буває пишне. Всі хвилі гір зверху застеляні роскішними нивами, вкриті зеленими сахарськими буряками, житами, пшеницями, білими гречками. Горяче сонце обливає жовті жита, пшениці, ціле море зеленоі ярини, кидає проміння в зелені глибокі ярі, в темні дубові та грабові ліси. А над тими хвилями ярини та озимини високо чорніють козацькі гостроверхі и круглі могили, обсмаляні гарячим сонцем, а зверху блищить синє шатро широко роскинутого неба, шугають здорові орли, або сидять купами на могилах…\n" +
        "Між Корсуньом та Богуславом, в безкетті покручених та поламаних високих гір, стоіть велике село Семигори.\n" +
        "Од північного берега Росі йде глибокий та довгий яр між двома рядами ніби порепаних гір. Той яр доходить до круглоі, як голова, гори и росходиться на обидва боки рукавами. В тих ярах роскидане село Семигори. По всему яру йдуть рядом один за другим ставки з греблями. Греблі обсажені здоровими вербами. Між ставками подекуди зеленіють левади яснозеленою осокою: то давні ставища, на котрих повисихала вже вода. По один бік яру стоять дуже круті, густо порепані гори, перервані подекуди узенькими западистими долинками. Попід горами біліють хати, а за хатами зеленіють сади, висять на крутих горах, ніби зелені гнізда. По другий бік яру гори піднімаються двома східцями чи терасами: на низшому східці понад ставками стоять хати, коло хат ростуть старі сади. Густе гіля яблунь та груш скрізь понавішувалось через тини на дорогу. Старі високі, як дуби груші вкривають всю терасу, як густий ліс. Вища тераса вся вкрита старим, густим роскішним лісом од одного кінця села до другого. Глянеш на той ліс з високоі гори и не можеш одірвати од ёго очей. Такий він гарний, густий та здоровий! На круті горби, на узькі долини неначе хто кинув дорогу зелену оксамитову одежу, и та одежа грациозно зібгалась, повгиналась, позападала тисячами дивних форм. На синёму небі ліс вирізується на крутих горбах ніби здоровими дугами, вкриває круглі горби, як густа щетина, заливає морем зелені узькі западисті долини. На палкому сонці круті горби блищать ясним зеленим листом, таким ясним, що круглі верхи густого дерева одрізняються один од другого, як здорові зелені мячі. Між тими крутими освіченими горбами темніють западисті узькі долини. Ліс в долинах такий густий, неначе хто насипав туди купами зеленого листя. Темні западини вкриті тінню; тінь повита зверху легесеньким туманом. Ті поетичні западини навіть здалеки ніби дишуть тобі просто на лице лісовою прохолодою, лісовою жизню и такою поезию, од котроі душа ростає, як віск на сонці, од котроі фантазия оживає, тягне в ті місця якоюсь потайною силою и чарує, й лякає тією живою силою, захованою в тих дивних місцях природи… Довгий семигорський яр доходить до круглоі, як голова гори, котра виступила терасою. Під самим шпилем блищить ставок, обсаженний старими столітніми вербами, а на шпилі стоіть церква с пятьма банями, с кучерявими золотими хрестами, поставляними на позолочені серпи молодого місяця. Од церкви знов пішов на бік довгий яр и ввігнався в густий ліс. Вище од церкви на горі біліє здорова економия з високою покрівлею, з білими двома верхами. Коло економиі, під самим лісом, чорніють старі скирти панського хліба, жовтіють золотом ожереди свіжої соломи.\n" +
        "Одного літнёго теплого дня, перед Паликопою, Омелько Кайдаш сидів в своій повітці на ослоні й майстрував. Широкі ворота були одчиняні настіж. На ясному сонці чорна тінь у воротах здавалась ще темніщою, неначе коло повітки висів шматок чорного сукна. В тій чорній продухвині сидів, ніби намалёваний на чорному сукні, старий Кайдаш в білій сорочці, в білих широких штанах, підперезаний ремінним очкуром. Застіжка с чорного шнурка чорніла на ёго пазусі. Він стругав вісь, придавлюючи обома ногами підніжку. Широкі рукави білоі сорочки метлялись на повітрі, одсовувались до ліктів, а спід рукавів виглядали здорові загорілі жилаві руки, с чорним волоссям, с товстими, як шнурки, жилами. Невеликі темні й гострі Кайдашеві очі пильно дивились на струг. Широке лице ёго було бліде й сухе. Широкий та високий лоб був вкритий сухими тонкими зморшками. Виски позападали и на висках темніла в западинах тінь. Тонкий ніс висох и випнувся по середині гострим, тонким горбиком. Тонка довга шия с кісточкою на горлі за кожним махом струга то подавалась назад, то витягалась вперед; іі обхватував знизу узький на палець комірчик, вишитий червоною та синёю заполочею. Кучеряве чорне густе волося стреміло на голові, як пух, и блищало подекуди сивиною.\n" +
        "Зараз коло повітки на току два Кайдашеві сини, молоді парубки поправляли поди під стіжки, бо вже жнива кінчились и наставала возовиця. Старшого Кайдашевого сина звали Карпом, менчого — Лаврином. Кайдашеві сини були молоді парубки, обидва високі, рівні станом, обидва довгобразі й русяві, з довгими тонкими, трошки горбатими носами, з румяними губами, з узьким але мягким підборіддям. Карпо був широкий в плечах, з довгими тонкими руками, з батьківськими карими гострими очима, з блідуватим без румянця лицем. Ёго тонкі губи обведяні дуже виразно. Верхня губа піднімалася по середині в гору, спускалась на обидва боки круто вниз и знов ніби легенько закручувалась кінчиками в гору. Русяві вуси ёго вже закручувались над верхнёю губою. Тонкі пружки ёго блідого лиця з міцно стуляними тонкими губами мали в собі щось неласкаве, а гострі темні очі та два глибокі пружки між бровами робили ёго лице трохи сердитим.\n" +
        "Лаврин проворно совав заступом по землі, Карпо ледві володав руками, морщив лоба, міцно тулив губи и неначе сердився на свого важкого й тупого заступа. Веселому, жартовливому менчому братові хотілось говорити, старший знехотя кидав ёму по кільки слів.\n" +
        "— Карпе! промовив Лаврин, а коли ти будеш оце сватати? Адже ж оце перед Семеном тебе батько, мабуть, оженить.\n" +
        "— Посватаю, кого трапиться, знехотя обізвався Карпо.\n" +
        "— Сватай, Карпе, Палажку. Кращоі од Палажки нема на всі Семигори.\n" +
        "— То сватай, як тобі треба, сказав Карпо.\n" +
        "— Як би на мене, то я б сватав Палажку, сказав Лаврин: в Палажки брови, як шнурочки; моргне, ніби вогнем сипне. Одна брова варта вола, другій брові й ціни нема. А що вже гарна, як малёвана.\n" +
        "— Коли в Палажки очі витріщкуваті, як у жаби, а стан кривий, як у баби.\n" +
        "— То сватай Хіврю. Хівря доладня, як писанка.\n" +
        "— И вже доладня! Ходить так легенько, наче в ступі горох товче, а як говорить то носом свистить.\n" +
        "— То сватай Вівдю. Чим же Вівдя негарна? Говорить тонісінько, як сопілка грає, а тиха як ягниця.\n" +
        "— Тиха, як телиця. Я люблю, щоб дівчина була трохи бриклива та ще й с перцем, сказав Карпо.\n" +
        "— То бери Химку. Ця як брикне, то й перекинесся, сказав Лаврин.\n" +
        "— Коли в Химки очі, як у сови, а своім кирпатим носом вона чує, як у небі млинці печуть. А як ходить, то неначе решетом горох точить, такі викрутаси виробляє…\n" +
        "— А чого це ви поставали та руки поскладали та ще й верзете Бог зна, що? загомонів Кайдаш до синів: Чи то можна в таку пятницю паскудити язики? Ви знаєте, що хто сегодня спостить цілий день, той ніколи не потопатиме в воді и не вмре наглою смертю.\n" +
        "— В Семигорах нема де и втопитись, бо в ставках старій жабі по коліна, сказав Карпо.\n" +
        "— Говори дурню, нема де втопитись. Як Бог дасть, то и в калюжі втопитись, сказав батько.\n" +
        "— Хіба с корчми йдучи… сердито сказав Карпо и тим натякнув батькові, що батько любив часто заходити до корчми.\n" +
        "— Ти, Карпе, ніколи не вдержиш язика! все допікаєш міні гіркими словами…\n" +
        "Кайдаш плюнув и знов пішов у повітку стругати вісь.\n" +
        "Хлопці трохи помовчали, але перегодя, знов почали балакати попереду тихо, а далі все голосніще, а потім зовсім голосно.\n" +
        "— Карпе! тихо почав Лаврин, дуже охочий до гарних дівчат: скажи бо, кого ти будеш сватати.\n" +
        "— Ат, одчепись од мене, тихо промовив Карпо.\n" +
        "— Сватай Олену Головківну. Олена кругла, як цибулька, повновида, як повний місяць; в неі щоки, як яблука, зуби, як біла ріпа, в неі коси, як праник, ноги, як ставиці, сама дівка здорова як тур, як иде, то під нею аж земля стугонить.\n" +
        "— Гарна… мордою хоч пацюки бий, сама товста, як бодня, а шия хоч обіддя гни.\n" +
        "— Ну, то сватай Одарку Ходаківну: ця тоненька, як очеретина, гнучка станом, як тополя, личко маленьке й тоненьке, як шовкова нитка, губи маленькі, як рутяний лист. З маленького личка, хоч води напийся, а сама пишна як у саду вишня, а тиха, як вода в криниці.\n" +
        "Старий Кайдаш аж на бік сплюнув, а Карпо промовив: Вже й знайшов красуню! В Одарки лице, як тріска, стан, як копистка, руки, як кочерги, сама як дошка, а як иде, то аж кістки торохтять.\n" +
        "— Але ж ти й вередливий! то сватай Хотину Корчаківну, сказав Лаврин и засміявся.\n" +
        "— Чи ти здурів? Хотина як вигляне в вікно, то на вікно три дні собаки брешуть, а на виду в неі неначе чорт сім кіп гороху змолотив.\n" +
        "— А вже ж! оце взяв би той кадівб, що бублика ззіси, поки кругом обійдеш, а як иде, то задом крутить та…\n" +
        "Карпо прикинув таке слівце, що богомольний Кайдаш плюнув и знов вибіг с повітки.\n" +
        "Хлопці стояли один проти другого поспиравшись на заступи.\n" +
        "— Господи! чи в вас Бога нема в серці, що ви в таку святу пятницю паскудите язики, чи вам не треба помірати, чи ви не соромитесь святого сонечка на небі? Якого це бісового батька ви стоіте, згорнувши руки, діла не робите та тільки язиками чорт зна-що верзете, крикнув Кайдаш и почав присікуватись до синів та махати стругом, перед самим Карповим носом. Старий був нервий и сердитий и ще більше сердився од того, що в ёго од самого ранку и рісочки не було в роті.\n" +
        "— Тату! сказав гордо Карпо: ви покинули майструвати, а ми вам нічого не кажемо.\n" +
        "Старого неначе хто вщипнув. Він заговорив дрібно й сердито, наговорив синам сім мішків гречаноі вовни, не вважаючи на святу пятницю, та й пішов у повітку. Сини почали знов розмовляти.\n" +
        "— Коли я буду вибірати собі дівчину, то візьму гарну як квіточку, червону як калину в лузі, а тиху, як тихе літо. Хоч під лавкою полежу, та на хорошу погляжу, хоч за дровами, аби с чорними бровами, сказав веселий Лаврін.\n" +
        "— Міні аби була робоча та проворна. Я не дуже люблю дівчат с солодким маком, а люблю с перцем, щоб були трохи кусливі, як мухи в спасівку, сказав Карпо.\n" +
        "— То бери Мотрю, Довбишову старшу дочку. Мотря й гарна и трохи бриклива, и в неі й серце с перцем, сказав Лаврін.\n" +
        "— Карпе! чого це ти витріщив очі на яблуню, наче корова на нові ворота? спитав Лаврін.\n" +
        "Карпо ніби не чув ёго слів та все дивився грізними очима на зелене гілля, неначе хотів прогнати с перед очей ту мрію. А мрія все стояла и манила ёго. Карпо почув, що с краси тієі мріі ніби напився погожоі холодноі криничаноі води в горячий день.\n" +
        "Сонце почало повертати на вечірній круг. Кайдашиха вийшла с хати и прикрила очі долонею. Вона була вже немолода, але и не зовсім стара, висока, рівна, з довгобразим лицем, с сірими очима, з русявими бровами, с тонким рівним носом, с тонкими губами, з блідим лицем. Біла сорочка здавалась ще біліщою од чорноі запаски, од чорноі с червоними квіточками здоровоі хустки на голові. Маруся Кайдашиха з замолоду довго служила в дворі у пана, куди іі взяли дівкою. Вона вміла дуже добре куховарити и ще й тепер іі брали до панів та до попів за куховарку на весілля, на хрестини та на храми. Вона довго терлась коло панів, набралася од іх трохи паньства. До неі прилипла якась облесливість в розмові и повага до панів. Вона любила цілувати іх в руки, кланятись, підсоложувала свою розмову з ними солодкими словами. Попаді й небогаті паніі частували іі в покоях, садовили поруч с собою на стільці, як потрібну людину. Маруся пишала губи, осміхалась, сипала облесливими словами, як дрібним горохом. До природнёі звичайности украінськоі селянки в неі пристало щось уже дуже солодке, аж нудне. Але як тільки вона трохи сердилась, з неі спадала та солодка луска и вона лаялась и кричала на ввесь рот. Маруся була сердита.\n" +
        "— А йдіть, дітоньки, полуднувати та й батька кличте! крикнула Кайдашиха тонким голосом.\n" +
        "Лаврін покинув заступа и пішов до хати. Карпо стояв, спершись на заступ.\n" +
        "— Карпе! йди, серденько, полуднувати! кидай роботу. Омельку! кидай майструвати. Вже спів дня звернуло.\n" +
        "— Покинь міні полудень на столі: я зараз прийду, обізвався Кайдаш с повітки, не повертаючи голови.\n" +
        "Сини з матірю пішли в хату, а батько все сидів на ослоні та майстрував. Він не обідав тієі пятниці и не пішов полуднувати.\n" +
        "На дзвіниці вдарили в дзвін и тонкий дзвінкий гук задрижав и розлився по селі на три долини. Він ударився об близьку гору, вкриту лісом, одскочив и залунав коло дальшого шпиля, а там далі розлився десь далеко понад густим лісом та все лунав слабіще та тихіще и замирав в тихих лісових западинах, обзиваючись ніби десь під землею. Старий Кайдаш кинув струга и перехрестився. Він надів свиту й шапку, підперезався и пішов на гору до церкви.\n" +
        "— Омельку! Омельку! гукнула Кайдашиха тонким голосом: не забудь зайти с церкви до попа та візьми гроші за вози бо завтра треба йти в Богуслав на ярмарок. Адже ж завтра в Богуславі ярмарок. Чи чуєш?\n" +
        "— Та чую, чую! обізвався Кайдаш зза двору и пішов на гору до церкви.\n" +
        "— Та будь-ласка, не заходь до шинку. Пропєш гроші, не матимеш с чим йти на ярмарок, знов крикнула Кайдашиха, виглядаючи с сіней.\n" +
        "Кайдаш прийшов до церкви, церква була ще заперта. Він сів коло дверей на камяних східцях и поклав шапку коло себе. На горах за шпилями, вкритими лісом, пишно горів вечерній світ сонця. Всі шпилі тепер чорніли в тіні, а між ними в западини проривався світ пучками, заливав западини світом, пронизував кожний верх дерева и блищав крізь зелений лист, як через кришталь. Над лісом розлився дивний спокій, а дзвін гув та дрижав над шпилями, тричі одбиваючи свій гук. Кайдаш не зводив очей с тієі картини. Він сидів, як деревяний, а на ёго лиці розливався якийсь смуток та жаль. Сторож брязнув ключами, одмикаючи важкий здоровий замок. Кайдаш кинувся, аж затрусився.\n" +
        "Одчинили церкву. Прийшов священик з дяком и почав правити вечерню. Паламар був у полі. Кайдаш пішов у вівтар служити за паламаря, посвітив свічки перед образами и подав священикові кадильницю…\n" +
        "Церква була зовсім порожня, тільки в бабинці стояли три баби в намітках. Кайдаш молився, стоячи на колінах не зводив ясних очей с царських врат, а ёго широке бліде лице стало жовте, як віск.\n" +
        "Забравши гроші, Кайдаш пішов до дому, але при самій дорозі стояв шинк. Кайдаш не ів цілий день. Голод затяг ёму живіт, тягнув за печінки. — Треба випити хоч одну чарку горілки; одна чарка не зашкодить, бо вже од голоду аж шкура болить, подумав Кайдаш и зайшов у шинок.\n" +
        "В шинку було кільки чоловік. За столом сидів ёго кум з лисиною на всю голову. Кайдаш сів з ними за стіл и почав балакати, випивши чарку горілки.\n" +
        "— Оце, куме, так натомився, аж спина болить, промовив Кайдаш.\n" +
        "— Що ж ти таке важке робив? спитав ёго кум.\n" +
        "— Та все лагожу вози та підроблюю осі. Ота міні каторжна гора потрощила не одного воза! А вже скільки я осей поломав через ту иродову гору, то й полічити не можна.\n" +
        "Дорога в село ишла коло самого Кайдашевого города. Вона спускалась с крутого шпиля, як с печі. Вози с снопами часто котились з гори и тягли вниз за собою й волів.\n" +
        "— То застав синів трохи роскопати шлях, сказав кум.\n" +
        "— А хіба ж я один возитиму тудою снопи. Адже ж и ти возиш. Чом би тобі пак не роскопати, сказав Кайдаш, випиваючи другу чарку.\n" +
        "— Нема, бач, міні діла. Ніби я сижу, згорнувши руки, обізвався чоловік; а воно було б дуже добре роскопати спуск, ще так трошки наскоси.\n" +
        "— А вже ж наскоси, щоб, бач, було не так круто: так, приміром, од того чагаря та до мого тину, сказав Кайдаш, ще й палцем махнув наскоси.\n" +
        "— Або хоч и так, приміром, наскоси од твого тину, де стоіть стара груша, та до чагарника, сказав кум и махнув пальцем наскоси на другий бік. От и вози були б цілі, сказав він ще й губами цмокнув.\n" +
        "— Так було б ще луче… та ще як би взяти заступом поза тим сучим горбом, попід самим тином, сказав Кайдаш, випивши чарку и запаливши люльку: та вже й посадило той горб на шпині, неначе оту гулю на твоій лисині, куме! Вже той каторжний горб сидить міні отут у печінках.\n" +
        "— Коли б ти знав, то я вже через ёго підірвався; мене вже поруха взяла. Коли не ідь, то все підперай воза спиною, сказав кум: всю спину поколив ик бісовому батькові.\n" +
        "— И як ті люде іздили с такоі гори и не роскопали, одколи Семигори стоять, говорив Кайдаш, наливаючи чарку с кварти.\n" +
        "— Та мабуть, попереду не возили тудою снопів, обізвався один чоловік с кутка.\n" +
        "— Еге, не возили. Скільки я с покійним батьком потрощив возів! Раз трохи не задушився наш віл у ярмі. Віз покотився з горба тай потяг за собою воли. По один бік заніз поламався; віл вискочив, а з другого боку заніз був добрящий та й не подався. Другий він так таки й повис на ярмі! Лежить бідна худоба, аж язика висолопила, поки я приніс сокиру та й перерубав заноза.\n" +
        "Вже сонце зайшло, вже стало на дворі темно, а Кайдаш усе пив у шинку, доки не пропив половини грошей и вже пяний потягся до дому.\n" +
        "Кайдашиха с синами вже повечеряла. Вже в хаті полягали спати, як батько застукав у двері.\n" +
        "— Жінко! одчини! закричав Омелько и почав лупити з усієі сили кулаком у двері.\n" +
        "— А деж ти, волоцюго, волочився до сего часу? крикнула Кайдашиха с хати. Не одчиню! Ночуй на дворі, коли пропив гроші. Про мене, лягай там під тином.\n" +
        "— Одчини, бо вікна побю! репетував Кайдаш и лупив у двері ногою так, що поганенькі двері аж хрипли?\n" +
        "— Як побєш, то й повставляєш. Одначе завтра в Богуславі ярмарок, обізвалась с хати жінка.\n" +
        "Лаврін устав и одчинив батькові двері. Батько переступив поріг, заточився, поминув хатні двері та й пішов лапати стіни в темних сінях. Замісь дверей, він налапав драбину и звалив іі, потрапив на діжку з водою, скинув кружок и шубовснув у воду обома руками. Кайдашиха наносила повнісіньку діжку води. Вона через верх полилась до долу.\n" +
        "— Жінко! де ти в сучого сина діла двері! кричав Кайдаш. Чи це я вліз у ставок? Покарала мене свята пятниця. Прийдеться пропасти.\n" +
        "Кайдашеві здавалось, що він иде через узеньку греблю попід вербами, що він шубовснув з греблі у ставок. Він почав гвалтувати.\n" +
        "— Якого ти бісового батька кричиш, як несамовитий! крикнула с хати Кайдашиха. Хіба ж ти не бачиш, що ти в сінях?\n" +
        "— А може це я згубив очі на греблі? Нічогісінько не бачу, єй Богу нічогісінько! А може це кум повидирав міні баньки з лоба, говорив Кайдаш сам до себе: оце лиха моя годинонька! Як же оце я прийду до дому без очей?\n" +
        "Кайдаш махнув рукою и зачепив горщик на полиці. Горщик полетів Кайдашеві на голову и гепнув об землю.\n" +
        "— Яка це иродова душа кидається горшками. Марусе! та не кидайся бо! При… присягаюсь, що вже більше не буду.\n" +
        "Кайдашиха схопилася с постелі, кинулась до печі и почала роздувати жар, притуливши до ёго суху тріску. Огонь блиснув на всю хату и полився через одчиняні двері в сіни.\n" +
        "— О! кум вернув міні очі. Потривай же, лисий дідьку! Я тобі завтра… я тобі оддячу!\n" +
        "И с тими словами Кайдаш вліз у хату. Ёго ясні очі посоловіли. Лице було бліде, як віск. Рукава по лікті були мокрі и з іх текла потоками вода. На землі появились смужки та покручені фігури з водяних крапель, неначе разки намиста, роскидані й поплутані на всі лади.\n" +
        "— Побила мене лиха година та нещаслива! загомоніла Кайдашиха: с чим же ти поідеш завтра на ярмарок, коли пропив гроші? Треба соли, треба горшків, треба смоли. Чим ти будеш мазати вози? Адже ж настає возовиця. Та треба де чого накупити ик весіллю. Адже ж думаєш женити сина.\n" +
        "— Брешеш! я не пропив грошей. Осьдечки гроші, та тобі не дам, сказав Кайдаш, вдаривши рукою замісь кишені по припічкові. Дулю візьмеш, а не гроші.\n" +
        "— От тепер, тату, вже не будете в воді потопати та од наглоі смерти помірати, обізвався з лави Карпо насмішкуватим голосом.\n" +
        "— А ти чого обзиваєсся? Матері твоій сторч та в борщ! Спи о там, коли ліг, а то я тебе палицею зверху, сказав Кайдаш, заточившись и впавши на лавку.\n" +
        "— В палиці два кінці: один по міні, другий по вас, обізвався з лави Карпо.\n" +
        "— И годі вже тобі! Ище мало того крику, спиняла мати Карпа.\n" +
        "Кайдаш кинув свиту на лаву в куток, звалився але не достав головою до свити. Голова сгукнула, непаче хто кинув на лаву гарбуза. Він, як упав, так и захріп на всю хату. Кайдашиха погасила каганець, и в хаті все стихло и втихомирилось. Тільки собаки на дворі ще довго брехали, роздратовані незвичайним криком та світом у хаті в таку пізню добу. Всі поснули в хаті, тільки Карпо довго не спав а все неначе бачив під зеленою яблунею свою мрію в червоних косниках на голові та в червоному намисті з дукачем.\n" +
        "Кайдашева сімя̀ — II\n" +
        "Иван Левіцький\n" +
        "1879\n" +
        ".mw-parser-output .prp-pages-output #box_menu{margin:0 auto;width:22.5em;text-align:center;padding:0.5em 0}.mw-parser-output .prp-pages-output .m_item{display:inline-block;width:4em;text-align:center}\n" +
        "\n" +
        "Другого дня в суботу на святого Паликопи, Кайдаш з жінкою поіхав на ярмарок, звелівши синам забрати заступи та роскопати трохи дорогу з гори. Карпо й Лаврін зостались дома. Минув день. Сонце стояло на вечернёму прузі, а Кайдаш не вертався до дому. Карпо накинув свитку на плечі и пішов на той куток, де жила Мотря Довбишівна. Од учорашнёго дня вона не виходила в ёго з голови.\n" +
        "Довбиш був богатий чоловік; він жив на самому кінці села, там де глибокий яр входив у ліс узьким клином. В самому кутку того яру блищав маленький довбишів ставочок. Над ставком стояла довбишева хата, вся в черешнях. Од улиці було видно тільки шматок білоі стіни с сінешними дверима. Густі високі соняшники зовсім закривали од улиці вікна й стіни, як густий ліс.\n" +
        "Карпо йшов тихо, скоса поглядаючи на довбишів двір. Перед ним блиснув угол білоі стіни, підперезаний внизу червоною призьбою; зачорніли чорною плямою одчиняні двері з одвірками, помалёваними ясно-синёю фарбою с червоною узькою смужкою навкруги. Довбишова хата була нова, велика, добре вшита с чималими вікнами. Коло вікон висіли вікониці, помалёвані ясно-синёю фарбою, як літне небо.\n" +
        "Карпо став за двором и сперся на ворота. Мотря вийшла с хати з глиняником у руках. Вона збіралась мазати червоною глиною припічок. Другий глиняник з білою глиною стояв коло порога. Тоді була субота.\n" +
        "— Будь здорова, чорноброва! сказав Карпо, не здіймаючи бриля и легенько кивнувши головою.\n" +
        "— Будь здоров, не чорнобривий! обізвалась Мотря.\n" +
        "— А йди сюди, Мотре, щось маю тобі казати.\n" +
        "Карпо був білявий, але волося на ёго голові з вершечку було трохи рудовате.\n" +
        "— А хіба ж я рудий? То тільки собак дражнять рудими, сказав Карпо.\n" +
        "Мотря стояла під хатою проти білоі стіни. Висока на зріст, рівна станом, але не дуже тонка, с кремезними ногами, з рукавами, позасукуваними по лікті, с чорними косами, вона була ніби намалёвана на білій стіні. Іі загоріле румяне лице ще виразніще малювалось с чорними тонкими бровами, с темними блискучими, як терен, облитий дощем, очима. Од широкого лоба, обвитого двома кісми іі довгобразий вид зужувався вниз и кінчався мягким невеличким підборідком. Тонкий ніс був рівний. Тонкі темночервоні губи були міцно стуляні, а невеликі щоки з румянцем були ширші вгорі, під самими очима и трохи западали, спускаючись до рота. Всі пружки іі лиця були тонкі, трохи гострі а в очах блищали навіть білки, неначе поліроване срібло, або тугий перлемутр (перлова матиця). В цілому лиці, в очах було розлите щось гостре, палке, горяче, був розлитий розум с характером и трохи з злістю. Сонце било на Мотрю косим промінням, освічувало іі з одного боку, обливало жовтогорячий кісник на голові та червоне намисто на шиі.\n" +
        "— Мотре! чи дома твій батько та мати? спитав Кайдашенко зза воріт.\n" +
        "— Нема! поіхали на ярмарок. А тобі на що?\n" +
        "— Так собі питаю, сказав Карпо и помаленьку, не хапаючись, переліз через перелаз у двір.\n" +
        "— Чого це ти Кайдашенку, лазиш через наші перелази? Наші пороги для тебе дуже низькі, сказала Мотря…\n" +
        "Карпо не зачіпав дівчат, не жартував з ними. Дівчата звали ёго гордим.\n" +
        "— Та хоч би й високі, то перескочимо. Здорова була, Мотре! сказав Карпо, подаючи ій руку.\n" +
        "Мотря руки не подала и підставила глиняника. Карпо взяв іі за руку вище ліктя и здавив так, що Мотря крикнула на весь двір.\n" +
        "— Оцего я вже не люблю: крикнула Мотря и вдарила Карпа правою рукою по спині так, що аж луна пішла по садку.\n" +
        "— Тай упекла ж! ото легенька рука! Неначе перцем посипала, сказав Карпо, вхопившись рукою за те місце на плечі, де ёго вдарила Мотря. Карпові подобався Мотрин жарт.\n" +
        "— Купив хтось, та не скажу. Не питай, бо старий будеш, задріботіла Мотря и блиснула двома рядами маленьких дрібненьких зубів.\n" +
        "— Та покинь отого глиняника, сказав Карпо и хотів одняти од неі драного горшка.\n" +
        "Мотря сіпнула глиняника до себе; шматок горшка зостався в Карпових руках. Червона глина полилась по землі.\n" +
        "— Геть, отчепися од мене, бо мати лаятиме, що я й досі припічка не підвела, сказала Мотря, але не пішла в хату підводити припічка, а почала мазати призьбу. Мотрі хотілось пожартувати с Карпом. Тільки що вона почала мазати призьбу од порога, Карпо сів на призьбі.\n" +
        "— Ей встань, бо я й тебе підведу червоною глиною; будеш ще рудіщий, сказала Мотря, махаючи віхтем коло самого Карпа.\n" +
        "— Мотре! хто це тобі купив таке гарне намисто? спитав Карпо.\n" +
        "— Та вже ж не ти, сказала Мотря и знов махнула віхтем коло самого Карпа; Карпо посунувся ще далі.\n" +
        "— А як би я купив тобі намисто, щоб ти сказала?\n" +
        "— Не знаю, щоб я сказала, промовила Мотря.\n" +
        "Карпо одсунувся на самий край призьби; далі вже й призьби не було.\n" +
        "— Вставай, бо зіпхну! крикнула Мотря.\n" +
        "— А ну пхни, чи подужаєш, промовив Карпо и осміхнувся.\n" +
        "— Тікай, бо Єй-Богу пхну. Я не подивлюсь тобі в вічі, крикнула Мотря и замахнулась на Карпа віхтем. Червона глина бризнула трёма кровяними крапельками на білу Карпову сорочку.\n" +
        "Карпо схопився и зачепив ногою глиняник. Глиняник перекинувся и покотився з горбика. Карпо обернувся, щоб не помазати чобіт, и зачепив пятою другого глиняника з білою глиною, що стояв коло самого порога. Глиняник покотився на середину двора, а за ним протяглася біла стежка, неначе хто простелив од порога білий рушник.\n" +
        "— Чи ти здурів, чи ти збожеволів, крикнула Мотря на ввесь двір. Ой лишечко міні! що ж оце буде, як мати надійде з ярмарку?\n" +
        "— Візьми ж та поприбірай, бо я не знаю, що це міні мати скаже. Та же ж мати купила на ярмарку валёк, оцієі червоноі глини за цілого пятака, промовила Мотря жалібним голосом.\n" +
        "— А ну, Мотре, заплач! Я ще з роду не бачив, як дівчата за глиняниками плачуть.\n" +
        "— Добрі смішки! Як возьму оцёго віхтя та обмажу тобі голову, то ти більше не будеш міні глиняників перевертати.\n" +
        "Мотря нагнулась вхопила з землі віхтя с червоноі глини и вже замахнулась, щоб кинути ним на Карпа.\n" +
        "— Не сердься: найму завтра музики, промовив Карпо.\n" +
        "Мотря бачила, що Карпо женихається з нею и здержувала свій гнів. Другому паробкові вона би справді обмазала глиною потилицю.\n" +
        "Тільки що Мотря замахнулась віхтем, за вербами заторохтів кінський візок. Мотря спустила руку.\n" +
        "— Боже мій! Єй-Богу мати з батьком ідуть з ярмарку.\n" +
        "Карпо скочив через перелаз и пішов попід тином. По другий бік улиці котився візок и підкотився під ворота. Довбишка зараз угляділа під хатою дві смуги розлитоі глини и два глиняники, що качались серед двору.\n" +
        "— А це, дівко, що таке! крикнула мати з воза. Чи ти пяна, чи твереза, що поперекидала серед двора глиняники?\n" +
        "— Та тут ускочив у двір чийсь кабан. Як почала я ганятись за ним, а він, проклятий, як дременув попід хатою та й поперевертав обидва глиняники, говорила Мотря.\n" +
        "— Це мабуть рябий Парашин кнур! він, каторжний, скакає через тини, як собака, промовила мати. Чом же це ти не підвела попереду припічка, та заходилась коло призьби? говорила мати, ввійшовши в хату.\n" +
        "— Оце, Господи! чом, та чом? крикнула й собі Мотря. Хіба я знаю, чом я попереду ступила лівою ногою, а не правою. Як би не той каторжний кнур, бодай він луснув, я б досі все діло поробила, сказала Мотря, осміхаючись до стіни.\n" +
        "Карпо тим часом прийшов до дому и застав уже батька й матір дома. Тільки що він увійшов у двір, батько спитав ёго:\n" +
        "— Деж це ти, Карпе, був? може роскопував дорогу через гору?\n" +
        "— Через яку гору? спитив Карпо, не дивлячись на батька.\n" +
        "—  А через оту о! хіба не бачиш? сказав Кайдаш, показуючи рукою на крутий шпиль, що мало не висів над ёго садком. Яж вам обом казав, щоб ви трохи роскопали дорогу навскоси. Одначе сегодня не можна жати, а копати можна.\n" +
        "— Хіба я здурів, щоб гори роскопував, сердито обізвався Карпо.\n" +
        "— А як же ми возитимемо снопи? сказав батько.\n" +
        "— Так як и возили, знехотя сказав Карпо.\n" +
        "— А хіба ж мало осей ми там поламали?\n" +
        "— То ще з одну або зо дві поламаємо. Цілий куток іздить через гору, а я буду іі роскопувати. Оце справді штука!\n" +
        "— А хто ж іі роскопає, як ми не почнемо? Комусь треба почати, сказав батько.\n" +
        "— Як хтось почне, то й я копирсну заступом скільки там разів, сказав Карпо и пішов у хату.\n" +
        "— И я так само, обізвався Лаврін тай собі пішов у хату.\n" +
        "Старий Кайдаш тільки рукою махнув, роспрягаючи воли: були пани, шляху не роскопали, настала волость, а шлях все таки не роскопаний. Не буду ж и я ёго копати. Нехай ёго чорти роскопують, коли знайдуть у ёму смак, бубонів сам до себе Кайдаш.\n" +
        "На дзвіниці вдарили в дзвін. Старий Кайдаш зняв шапку, тричі перехрестився и пішов до церкви, загадавши синам ладнувати два вози з рублями для возовиці. Другого дня світом вони збірались іхати на поле по снопи, не вважаючи на те, що була неділя. Селяне поважають неділю й празники и не роблять ніякоі роботи, але не мають за гріх одного діла: возити в неділю та в празник снопи.\n" +
        "В неділю вранці перед службою Мотря Довбишівна прибіралася до церкви. Вона принесла с хижки завязані в хустці квітки та стрічки и розсипала іх по столі, застеляному білою скатертею, принесла й поставила на лаві червоні сапянці. На кілку вона повісила зелену с червоними квітками спідницю. Спідниця так злежалась у складках у скрині, що стирчала, неначе була накрохмаляна. Довбишівна сіла на круглому дзигликові коло стола, а подруга сусіда клала ій на голову стрічки. Вона наділа Мотрі на голову кибалку, вирізану с товстого паперу, на три пальці завширшки, похожу на вінок; на кибалку над самим лобом, поклала узеньку стрічку з золотоі парчі, а потім клала стрічки одну вище другоі, так що над лобом було видко пружок од кожноі стрічки. Всю кибалку пругом и всі коси вона обтикала квітками с червоних, зелених, синіх, жовтих узеньких стяжок. За вуха вона позатикала пучки дрібненького барвінку, качурові кучері та павине піря и потім розстелила по спині двайцять довгих кінців стрічок до самого пояса.\n" +
        "— Нащо це ти, Мотре, так прибіраєсся? спитала іі мати: тепер же невелике свято. Нащо ти надіваєш всі квітки та стрічки.\n" +
        "— Та коли залежались у скрині. Хочу трохи провітрити на дворі, сказала Мотря, але в неі була зовсім инча думка. Карпо обіцяв для неі найняти музики. Вона сподівалась побачитись з ним у церкві.\n" +
        "Мотря вбралася в зелену спідницю, в червону запаску, підперезалась довгим червоним поясом и попускала кінці мало не до самого долу, одяглась в зелений с червоними квіточками горсет, взулась в червоні чоботи, наділа добре намисто, взяла в руку білу хусточку та й вийшла на двір, як зоря зійшла. Вся іі голова горіла проти сонця, здоровим вінком с квіток та зеленого листя. Павине піря блищало й мигало, а золотий пружок парчі на чорних косах сяв, як сонце и придавав краси тонким чорним бровам та блискучим очам. Мотря йшла попід зеленими садами, неначе райська птиця линула и закрасила собою сади червоними чобітьми та стрічками.\n" +
        "Вона дійшла до Кайдашевого двора. Саме тоді с крутого шпиля, зъізджали два вози с снопами, неначе два стіжки котилися з гори. То віз снопи Кайдаш з двома синами. Високі вози посхилялись на волів и кололи іх в спину гострою соломою та остюками. Воли аж позадерали голови в гору та повитріщали здорові очі.\n" +
        "— Карпе! держи цабе! крикнув батько на сина. Поминай колесом отой каторжний горбик.\n" +
        "— Цабе, сірий! цабе, моругий! крикнув Карпо и крутнув батогом над рогатими головами.\n" +
        "Але саме в той час він глянув униз. Проз іх двір йшла Мотря, неначе райська птиця линула, вся в квітках та стрічках. Червона запаска, червоні чоботи, червоний як жар, пояс, все блищало й сяло проти раннёго сонця, як червоне золото. Карпо задивився на те диво, а віз вискочив уже одним колесом на крутий горбок.\n" +
        "— Держи цабе! крикнув не своім голосом старий Кайдаш, побачивши, що віз нахиляється на один бік. Чи ти оглух, чи ти осліп! Карпе, держи цабе!\n" +
        "Карпо не міг одірвати очей од Мотрі, а віз усе нахилявся на бік. Батько кинув заднёго воза и побіг з гори до переднёго, та все кричав: цабе, сірий, цабе! Віз вискочив колесом на горбок; и з усієі сили перекинувся на бік. Передня вісь хруснула, як тріска, а колесо завязло в рівчаку.\n" +
        "— Ой лиха моя година та нещаслива! крикнув Кайдаш. Цеж мене покарала свята неділя. И нащо було сегодня іхати по снопи!\n" +
        "Не встиг Кайдаш набідкатись, як задній віз нагнався на передній. Кайдаш спиняв воли, бив іх пужальком по морді; воли позадирали голови вгору, повитріщали очі. Ярмо врізалось в іх товсті шиі. Довгі волячі воля моталися коло ярма, як шматки полотна. А воли все таки гнались уперед, аж бігли. Важкий віз пхав іх з заду прямо на переднёго воза. Кайдаш обперся руками об воза и з усієі сили пхав ёго на бік, але все те нічого не помогло. Воли наскочили прямо на колесо переднёго воза, що стреміло на повітрі. Колесо покрутилось на осі, вісь хруснула, як ломачка, и задній віз поліг на перекинутий передній. Один передній віл упав у рівчак и душився в ярмі. В ёго з рота текла слина.\n" +
        "Тим часом на дзвіниці вдарили в усі дзвони. Загув, заревів великий дзвін и пішла луна по далеких ярах, по далекому лісі; задзвеніли дрібно маленькі дзвони, задзеленькала луна в лісових долинах, неначе хтось у лісі грав на кобзі та на цимбалах. Всі люде, що сиділи коло церкви, повставали и почали хреститись. Кайдашеві було видко увесь шпиль, на котрому стояла церква, всіх людей коло церкви. Він зняв шапку и почав хреститись.\n" +
        "— Господи милостивий та милосердний! Покарала мене и свята неділя и свята пятниця. Тепер хоть сядь та й плач! говорив Кайдаш и мало не плакав.\n" +
        "— Вас, тату, все карає як не пятниця, так неділя, сказав Карпо насмішкувато.\n" +
        "— Ти вже в нас великорозумний! Коли б було копирснути хоч раз заступом того каторжного горбика. Що ж тепер будемо на світі божому робити! бідкався старий Кайдаш.\n" +
        "— Кидаймо снопи та ходімо до церкви, сказав Карпо.\n" +
        "Карпо глянув на вози и важко здихнув. Треба було братись за роботу. Кайдашенки попробували одкотити заднёго воза, але побачили, що ёго так трудно одкотити, як трудно пересунути стіжки. Ім прийшлось скинути половину снопів підвести вози, скласти снопи знов на віз и одвезти на тік. Поки вони вернулись назад, в роскиданих снопах уже рились свині, и зарились так, що тільки було видно задні ноги с хвостами; десь узялись гуси, качки, вкрили снопи, як галич, ростягували по соломині, по колоскові, кричали, геготали. Горобці обсіли ті снопи, що скотилися далеко вниз. С сусідських городів півні понаводили курей, неначе паничі паннів; квочки вивели курчат на гулянку, а шинкарева коза вилізла на віз, на самісінький верх и тільки борідкою махала, смикаючи колоски.\n" +
        "Лаврін вернувся с току с цілим возом, махнув батогом по козі; коза мекнула коротко, неначе горло ввірвала, и скочила на свиней. Свині кинулись в ростіч, гуси наробили гвалту й розсипались по горі.\n" +
        "Всі малі хлопці й дівчата покинули слухати службу, повилазили на дзвіницю поставали на горі коло брами и дивились на диво. Вже задзвонили на достойно, як Кайдаш с синами впорався коло воза, повіз снопи в двір, а на горі зостався тільки поламаний віз, неначе поламаний бурею корабель, викинутий на берег.\n" +
        "Старий Кайдаш накинув свиту и пішов до церкви одмолюватись за свій гріх. За ним слідком пішов и Карпо, щоб подивитись на Мотрю.\n" +
        "Карпо перейшов цвинтар и тільки встиг кинути очима на Мотрю. Вона навмисне стояла коло дівчат с самого краю. Карпо ледві вглядів на ході іі гострі, як ніж, очі, ухопив іі блискучий погляд, с під цілого вінка квіток та зеленого листя.\n" +
        "Виходячи с церкви, Карпо догнав Мотрю за брамою. Люде сипнули с церкви и розсипались по всему шпилі. Дівчата й діти побігли з гори, неначе ластівки полетіли, а Мотря побігла, неначе сива зозуля полинула. Іі довгі стрічки тільки маяли на вітрі, як листя роскішного хмелю, що почеплявся на тополі. Карпо догнав іі коло свого двору. Мотря закрила губи хустиною, але зараз іх одкрила и сміливо спитала, чи вийде він по обіді на музики.\n" +
        "— Вийду! а ти, Мотре, вийдеш?\n" +
        "— Ой важу я на цю дівчину вражу, та не знаю, чи буде вона моєю; вється, як вюн руках, та коли б не вискочила з рук, подумав Карпо тай пішов у хату.\n" +
        "По обіді на улиці вдарили троісті музики и пішли через село до корчми, виграваючи дорогою. Заворушились дівчата на городах та в садках, висипали на улицю, аж перелази затріщали. Жнива кінчались, наставав вольніший час. Дівчата збірались на гулянку під корчмою. Корчма стояла коло одноі греблі над ставком, між високими вербами. Всі дівчата були тільки в червоних кибалках, одна Мотря прийшла вся в квітках та в стрічках. Дівчата оглядались одна на другу та все поглядали на Мотрю. Між парубками зачорніла висока смушева Карпова шапка. Карпо найняв музики дівчатам. Всі дівчата здивувались. Ніхто не знав, що він найняв музики для одноі Мотрі. Мотря пішла у танець и повела за собою других дівчат. За дівчатами пішли в танець хлопці. Тільки Карпо стояв оддалеки заклавши одну руку за пояс. Він не любив и не вмів танцювати. Оддалеки він спід лоба дивився на Мотрю, як по іі плечах маяли довгі кінці стрічок, як дріботіли в танцях іі червоні чоботи, як брящало на шиі добре намисто з дукачами.\n" +
        "Музики разом стали, неначе струни порвали. Дівчата перестали танцювати. Карпо все стояв та скоса поглядав на Мотрю. Він не приступив до неі, не розмовляв з нею. Мотрю почала брати злість. Над вечір дівчата почали росходитись. Пішла до дому й Мотря, трохи сердита на Карпа. Карпо догнав іі, пристав до неі, пішов з нею поруч, але довго не говорив з нею ні слова. Мотря мовчки лузала насіння. Довбишів двір був недалечко. Вже було видко садок и задимляний верх. Вони пішли греблею:\n" +
        "— Чого це ти, парубче, слідком йдеш за мною? Мати вглядить та ще й вилає, сказала Мотря не дивлячись на Карпа.\n" +
        "— Я лайки не дуже боюся. Чи вийдеш у вечері на вулицю?\n" +
        "— Може до тебе й друга вийде, хто тебе знає… сказала й слово перервала Мотря.\n" +
        "— А як я свисну за садком, чи вийдеш?\n" +
        "— Я б обсадила черешнями двір, щоб и твого голосу не було чути.\n" +
        "— Чому ж так?\n" +
        "— Хто тебе знає, чи ти гордий, чи ти пишний, чи гордо несесся. Я не знаю, чи ти мене вірно любиш, чи з мене смієсся. Ще й слави на все село наробиш.\n" +
        "— Я не гордий, я не пишний й гордо не несуся. Я тебе, Мотре, щиро люблю и с тебе не сміюся.\n" +
        "Мотря стала якось добріща й ласкавіща. Вона осміхнулась и глянула Карпові просто в вічі. Іі блискучі очі неначе легка роса присипала.\n" +
        "— Як зійдуть зорі на небі, я видам матері вечерю та й вискочу на часок у садок. Прощай, Карпе! сказала Мотря и крутнулась перед ним так швидко, що іі стрічки обсипали ёму лице, ніби пухом.\n" +
        "— Ой ти, дівчино, с кучерявоі рути-мяти звита; та з гостролистоі шельвіі! подумав Карпо и повернув назад до дому.\n" +
        "Минуло неділь зо дві. Вже кінчалось літо. Перед самим Семеном Карпо заслав до Мотрі старостів. Старости заміняли хліб: Мотря не цуралась Карпа.\n" +
        "Після Семена старий Кайдаш надів нову чорну свиту, засунув за пазуху паляницю, взяв у руки ціпок и пішов с своєю жінкою до Довбишів на розглядини. Кайдашиха вбралась, як у неділю, в горсет, в жовті чоботи, в нову білу свиту, ще й засунула в рукав білу хусточку. Довбиші були богатенькі, и Кайдашеві хотілось себе показати перед богачами.\n" +
        "Кайдаш из жінкою ввійшов у Довбишів двір. На дворі було горяче, як літом. Сонце тільки що звернуло с півдня. Кайдашиха стала коло воріт и обтерла полою пил з жовтих чобіт. Недалеко од хати під грушею Мотря терла коноплі. Іі руки ходили ходором. Терниця гавкала під іі руками, як сучка, дрібно та голосно, аж скрипіла, аж вила. Жменя конопель маяла в іі руці, як лисичий хвіст.\n" +
        "— Добри-день, моя дитино! Боже поможи! промовила Кайдашиха до Мотрі тоненьким голосом.\n" +
        "— Доброго здоровя! спасибі! обізвалась Мотря с садка, и іі руки не переставали ворушити мечин терниці. Вона тільки підвела голову в гору и знов спустила очі на терницю.\n" +
        "— Чи батько та мати дома? спитала Кайдашиха.\n" +
        "— Дома. Вони в хаті, обізвалась Мотря, и терниця замовкла на хвилину та й знов загавкала на ввесь садок.\n" +
        "Довбишка виглянула в вікно и догадалась, що Кайдаші йдуть на розглядини. Вона міттю застлала скатертею стіл, поклала на столі хліб, накинула на себе горсет, а Довбиш вискочив у сіни, вскочив у хижку и накинув на себе свиту.\n" +
        "Ще Кайдашиха розмовляла на дворі з Мотрею, а Довбишка одчинила сінешні двері й стала на порозі. Кайдаші привитались до Довбишки. Хазяйка попросила іх в хату. В сінях гостей зострів Довбиш и поцілувався з ними. Всі вони ввійшли в хату, и гості знов поздоровкались с хазяінами.\n" +
        "Кайдашиха поклала на стіл паляницю. Довбишка взяла паляницю в руки, поцілувала и знов поклала на стіл.\n" +
        "— Як вас, свахо, Бог минув? Чи живі, чи здорові, моє серденько? говорила Кайдашиха тонким голосом та все пишала губи.\n" +
        "— Спасибі вам, свахо! Живемо потрошку, хвалити Бога. Сідайте, свахо, щоб старости сідали, просила хозяйка.\n" +
        "— Та дай же, Боже, щоб старости сідали. Як дасть Господь милосердний, то може и справді старости незабаром сядуть у вас, говорила Кайдашиха, втераючи губи й вид хусточкою, хоч на губах и на виду нічогісінько не було.\n" +
        "— Чи це ви, свахо, запилились? спитала в Кайдашихи хазяйка.\n" +
        "— Еге, моє серденько. На дворі душно, неначе серед літа, сказала Кайдашиха и знов у друге обтерла вид хусточкою. Вона любила чепуритись и держала себе дуже чисто. Все на неі було чистеньке, неначе нове.\n" +
        "Кайдашиха сіла коло стола на ослоні. Кайдаш балакав с хазяіном.\n" +
        "— Та сідайте бо, свахо, за стіл! просила хазяйка.\n" +
        "Кайдашиха пересіла з ослона на лаву. Вона дуже церемонилась и була прохана. Пробуваючи на службі в панів, вона набралась од іх чимало пишання.\n" +
        "— Та сідайте бо, свахо, за стіл, будьте ласкаві. Оце, Господи! А ви, свату, чого це стоіте? Сідайте за стіл, а то ще й старости наші спротивляться.\n" +
        "Кайдаш поліз за стіл. Кайдашиха тільки трошки посунулась по лаві до стола, й очі спустила до долу.\n" +
        "— Оце, Господи! сідайте бо, свахо, коли ваша ласка, на покутя! Ви ж таки наша сваха, припрошувала хазяйка Кайдашиху.\n" +
        "Кайдашиха зовсім спустила очі, запишалась, втерла губи хусточкою и посунулась на саме покутя. Вона ледві підвела очі и глянула на хату.\n" +
        "— Та вже й робоча ваша дочка! Що за золота в вас дитина. Там так пильнує коло роботи, що й не розгинається. Ото, моє серце, гарну невісточку матиму, коли дасть Господь милосердний довести діло до ладу, заговорила Кайдашиха, неначе в розмові мед розлила по хаті.\n" +
        "Довбишка гукнула на Мотрю. Мотря ввійшла в хату и стала коло порога. Мати загадала ій зібрати з глечика сметану та накраяти сала. Сама хазяйка накраяла хліба а хозяін вніс с хижки бокату пляшку горілки и поставив на стіл. В горільці плавав червоний стрючок перцю, неначе тільки що вирваний на городі. Кайдаш глянув на перець, и в ёго слинка потекла.\n" +
        "Мотря поставила на стіл полумисок с сметаною и тарілку с шматочками сала. Кайдашиха не зводила з Мотрі очей, неначе хотіла випитати всю іі душу. Іі очі з мякеньких стали зразу тверденькі. Брови насупились, а осміх злетів з уст и ніби сів десь на образах.\n" +
        "— Спасибі тобі, моє серце кохане, що ти нас витаєш, промовила Кайдашиха до Мотрі, и знов на іі уста прилинув осміх, а с словами неначе полилась патока.\n" +
        "Кайдашиха сиділа, згорнувши руки, ніби тільки що запричастилась и прийшла с церкви.\n" +
        "Мотря підвела на будущу свекруху гострі очі й постерегла ту патоку своім пронизуватим розумом. Той солодкий медок зразу не сподобався Мотрі.\n" +
        "Тим часом Довбишка звеліла дочці роскласти в челюстях трісок и спражити яєшню. Мотря почала поратись коло печі. Хазяін налив чарку перцівки. В Кайдаша натекло повний рот слини. Він насилу вдержався, щоб не плюнути під стіл.\n" +
        "Хазяін підняв чарку вгору и почав приказувати: даруй же, Боже, нам щастя и здоровя, а помершим пошли, Господи, царство небесне. Поможи нам, Боже, довести діло до кінця, а ти, дочко, будь щаслива й здорова. Як будеш свекрові та свекрусі покірненька, буде твоя голівонька веселенька!\n" +
        "Хазяін випив усю чарку до самого дна, щоб не зоставалось на слези, знов налив и подав Кайдашеві. Кайдаш устав, приказав до чарки кілька слів и швидче вкинув у рот горілку. Хазяін знов налив чарку и подав Кайдашисі. Кайдашиха взяла чарку и наговорила приказок живим и мертвим повнісіньку хату.\n" +
        "— Даруй же, Боже, нам и нашим дітям вік довгий та щасливий, щоб ти, моя дочко, була здорова, як вода, щоб цвіла до віку, як рожа, щоб ти закрасила мою хату, моя втіхо, як зозуля садочок, приголубила мою старість. Пошли тобі, Боже, вік веселий, як рибі в морі.\n" +
        "Кайдашиха ледві помочила губи в горільці, хоч и любила горілочку.\n" +
        "Кайдаш глянув на жінку и подумав: и на якого нечистого вона распустила язики! Ёму дуже хотілось випити по другій.\n" +
        "— Що це ви, свахо, так мало випили! припрохувала хазяйка.\n" +
        "— Ой буде, буде! залепетала Кайдашиха: така гірка, як полинь! Я не знаю, як ті пяниці іі пють.\n" +
        "— Та випийте бо, свахо, більше. Не вже оце ви зоставляєте стільки на слези? просили хазяйка.\n" +
        "Кайдашиха знов притулила губи до чарки и мало не помилилась та не хильнула до дна, але якось удержалась и вкинула в рот один ковток.\n" +
        "— Та випийте, бо свахо, повну, знов просила хазяйка.\n" +
        "— Ой буде, моє серденько! Коли б не впитись, сказала Кайдашиха и оддала хазяйці чарку в руки, закусивши хлібом та салом.\n" +
        "Довбиш налив чарку й покликав до столу Мотрю. Мотря взяла чарку, ледві промовила кілька слів, дуже швидко притулила чарку до губ и ще швидче іі одвела, неначе губи чаркою попекла, й одвернулась, втираючись рукавом.\n" +
        "Гості й хазяіни почали полуднувати, знов випили по чарці й розговорились. Кайдашиха щебетала, але все крадькома скоса поглядала очима на скриню, що стояла на полу, на жертку, на подушки. Вона дуже любила чванитись и почала росказувати, як іі шанували пани та попи.\n" +
        "— Оце недавно, серденько моє, просили мене готувати обід аж у Дежки; у священика були хрестини. Господи милосердний! наіхало гостей повнісінькі хати, а я на всіх настачила. Вже як порозъіздились гості, а матушка й кличе мене в покоі, садовить мене на стільці за столом, и сама сідає зо мною вечеряти. Так мене частувала, спасибі ій, та все припрохує: та випийте бо, пані Марусе, та іжте бо, пані Кайдашихо! Єй-Богу правду кажу, проше вас!\n" +
        "Мотря одвернулась до порога й засміялась. С того проше сміялись на всему селі и дражнили через те слово Кайдашиху пані ікономшою.\n" +
        "Та згадка про панський двір навела думку про недавню панщину, навела сум на всіх. Кайдашиха примітила теє и звернула на инчу стежку.\n" +
        "— А що вже про своіх синів, то, єй-Богу, гріх буде не хвалити іх. В мене два сини, як два соколи. Що вже що, а на старість прикриють мене орлиними крилами. Хвалити Бога, буде до кого прихилитись. Що за люба дитина мій Карпо; такий слухняний, такий тихий, хоч у вухо бгай. Такий він був и маленьким: оце було покину в колисці, піду на город, вернуся, а він лежить, ані писне. Моі сини, як пахучі васильки на городі.\n" +
        "Довбиш и Довбишка слухали Кайдашиху, аж роти пороздявляли, а Кайдаша брала злість. Він усе ждав, щоб ёго жінка скоріще стулила рота, та щоб хазяін наливав по чарці. Червоний перець у горільці дражнив ёго, як цяцька малу дитину, а жінка роспустила розмову на всю губу. Він не видержав.\n" +
        "— И годі тобі хвалитись дітьми. Хвалила ж сова своіх дітей, що нема кращих на світі, а яка ж там совина краса! сказав Кайдаш.\n" +
        "— А вже ж, що правда, то не гріх, притакнула Довбишка и неначе підлила масла в огонь.\n" +
        "— Я не хвалю своіх синів, але коли правду сказати, то на всі Семигори немає таких хлопців, як моі. Що вже робочі, слу";
}
